This Terraform configuration creates a basic AWS IAM user example. It defines:

- An AWS provider using the `us-east-1` region
- An IAM user
- An IAM group
- A basic IAM policy allowing read-only access to IAM account details
- Attachment of the policy to the group
- Membership of the user in the group

```hcl
terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_user" "basic_user" {
  name = "basic-example-user"

  tags = {
    Name        = "basic-example-user"
    Environment = "example"
  }
}

resource "aws_iam_group" "basic_group" {
  name = "basic-example-group"
}

